   345→    pub fn protocol(&self) -> Protocol {
   346→        match self {
   347→            SupportedProtocol::StatusV1 => Protocol::Status,
   348→            SupportedProtocol::StatusV2 => Protocol::Status,
   349→            SupportedProtocol::GoodbyeV1 => Protocol::Goodbye,
   350→            SupportedProtocol::BlocksByRangeV1 => Protocol::BlocksByRange,
   351→            SupportedProtocol::BlocksByRangeV2 => Protocol::BlocksByRange,
   352→            SupportedProtocol::BlocksByRootV1 => Protocol::BlocksByRoot,
   353→            SupportedProtocol::BlocksByRootV2 => Protocol::BlocksByRoot,
   354→            SupportedProtocol::BlobsByRangeV1 => Protocol::BlobsByRange,
   355→            SupportedProtocol::BlobsByRootV1 => Protocol::BlobsByRoot,
   356→            SupportedProtocol::DataColumnsByRootV1 => Protocol::DataColumnsByRoot,
   357→            SupportedProtocol::DataColumnsByRangeV1 => Protocol::DataColumnsByRange,
   358→            SupportedProtocol::PingV1 => Protocol::Ping,
   359→            SupportedProtocol::MetaDataV1 => Protocol::MetaData,
   360→            SupportedProtocol::MetaDataV2 => Protocol::MetaData,
   361→            SupportedProtocol::MetaDataV3 => Protocol::MetaData,
   362→            SupportedProtocol::LightClientBootstrapV1 => Protocol::LightClientBootstrap,
   363→            SupportedProtocol::LightClientOptimisticUpdateV1 => {
   364→                Protocol::LightClientOptimisticUpdate
   365→            }
   366→            SupportedProtocol::LightClientFinalityUpdateV1 => Protocol::LightClientFinalityUpdate,
   367→            SupportedProtocol::LightClientUpdatesByRangeV1 => Protocol::LightClientUpdatesByRange,
   368→        }
   369→    }
