   429→impl<E: EthSpec> UpgradeInfo for RPCProtocol<E> {
   430→    type Info = ProtocolId;
   431→    type InfoIter = Vec<Self::Info>;
   432→
   433→    /// The list of supported RPC protocols for Lighthouse.
   434→    fn protocol_info(&self) -> Self::InfoIter {
   435→        let mut supported_protocols = SupportedProtocol::currently_supported(&self.fork_context);
   436→        if self.enable_light_client_server {
   437→            supported_protocols.push(ProtocolId::new(
   438→                SupportedProtocol::LightClientBootstrapV1,
   439→                Encoding::SSZSnappy,
   440→            ));
   441→            supported_protocols.push(ProtocolId::new(
   442→                SupportedProtocol::LightClientOptimisticUpdateV1,
   443→                Encoding::SSZSnappy,
   444→            ));
   445→            supported_protocols.push(ProtocolId::new(
   446→                SupportedProtocol::LightClientFinalityUpdateV1,
   447→                Encoding::SSZSnappy,
   448→            ));
   449→        }
   450→        supported_protocols
   451→    }
   452→}
