   579→    /// Returns `true` if the given `ProtocolId` should expect `context_bytes` in the
   580→    /// beginning of the stream, else returns `false`.
   581→    pub fn has_context_bytes(&self) -> bool {
   582→        match self.versioned_protocol {
   583→            SupportedProtocol::BlocksByRangeV2
   584→            | SupportedProtocol::BlocksByRootV2
   585→            | SupportedProtocol::BlobsByRangeV1
   586→            | SupportedProtocol::BlobsByRootV1
   587→            | SupportedProtocol::DataColumnsByRootV1
   588→            | SupportedProtocol::DataColumnsByRangeV1
   589→            | SupportedProtocol::LightClientBootstrapV1
   590→            | SupportedProtocol::LightClientOptimisticUpdateV1
   591→            | SupportedProtocol::LightClientFinalityUpdateV1
   592→            | SupportedProtocol::LightClientUpdatesByRangeV1 => true,
   593→            SupportedProtocol::StatusV1
   594→            | SupportedProtocol::StatusV2
   595→            | SupportedProtocol::BlocksByRootV1
   596→            | SupportedProtocol::BlocksByRangeV1
   597→            | SupportedProtocol::PingV1
   598→            | SupportedProtocol::MetaDataV1
   599→            | SupportedProtocol::MetaDataV2
   600→            | SupportedProtocol::MetaDataV3
   601→            | SupportedProtocol::GoodbyeV1 => false,
   602→        }
   603→    }
   604→}
