   646→/* Inbound upgrade */
   647→
   648→// The inbound protocol reads the request, decodes it and returns the stream to the protocol
   649→// handler to respond to once ready.
   650→
   651→pub type InboundOutput<TSocket, E> = (RequestType<E>, InboundFramed<TSocket, E>);
   652→pub type InboundFramed<TSocket, E> =
   653→    Framed<std::pin::Pin<Box<Compat<TSocket>>>, SSZSnappyInboundCodec<E>>;
   654→
   655→impl<TSocket, E> InboundUpgrade<TSocket> for RPCProtocol<E>
   656→where
   657→    TSocket: AsyncRead + AsyncWrite + Unpin + Send + 'static,
   658→    E: EthSpec,
   659→{
   660→    type Output = InboundOutput<TSocket, E>;
   661→    type Error = RPCError;
   662→    type Future = BoxFuture<'static, Result<Self::Output, Self::Error>>;
   663→
   664→    fn upgrade_inbound(self, socket: TSocket, protocol: ProtocolId) -> Self::Future {
   665→        async move {
   666→            let versioned_protocol = protocol.versioned_protocol;
   667→            // convert the socket to tokio compatible socket
   668→            let socket = socket.compat();
   669→            let codec = match protocol.encoding {
   670→                Encoding::SSZSnappy => SSZSnappyInboundCodec::new(
   671→                    protocol,
   672→                    self.max_rpc_size,
   673→                    self.fork_context.clone(),
   674→                ),
   675→            };
   676→
   677→            let socket = Framed::new(Box::pin(socket), codec);
   678→
   679→            // MetaData requests should be empty, return the stream
   680→            match versioned_protocol {
   681→                SupportedProtocol::MetaDataV1 => {
   682→                    Ok((RequestType::MetaData(MetadataRequest::new_v1()), socket))
   683→                }
   684→                SupportedProtocol::MetaDataV2 => {
   685→                    Ok((RequestType::MetaData(MetadataRequest::new_v2()), socket))
   686→                }
   687→                SupportedProtocol::MetaDataV3 => {
   688→                    Ok((RequestType::MetaData(MetadataRequest::new_v3()), socket))
   689→                }
   690→                SupportedProtocol::LightClientOptimisticUpdateV1 => {
   691→                    Ok((RequestType::LightClientOptimisticUpdate, socket))
   692→                }
   693→                SupportedProtocol::LightClientFinalityUpdateV1 => {
   694→                    Ok((RequestType::LightClientFinalityUpdate, socket))
   695→                }
   696→                _ => {
   697→                    match tokio::time::timeout(
   698→                        Duration::from_secs(REQUEST_TIMEOUT),
   699→                        socket.into_future(),
   700→                    )
   701→                    .await
   702→                    {
   703→                        Err(e) => Err(RPCError::from(e)),
   704→                        Ok((Some(Ok(request)), stream)) => Ok((request, stream)),
   705→                        Ok((Some(Err(e)), _)) => Err(e),
   706→                        Ok((None, _)) => Err(RPCError::IncompleteStream),
   707→                    }
   708→                }
   709→            }
   710→        }
   711→        .boxed()
   712→    }
   713→}
   714→
   715→#[derive(Debug, Clone, PartialEq)]
   716→pub enum RequestType<E: EthSpec> {
   717→    Status(StatusMessage),
   718→    Goodbye(GoodbyeReason),
   719→    BlocksByRange(OldBlocksByRangeRequest),
   720→    BlocksByRoot(BlocksByRootRequest),
   721→    BlobsByRange(BlobsByRangeRequest),
   722→    BlobsByRoot(BlobsByRootRequest),
   723→    DataColumnsByRoot(DataColumnsByRootRequest<E>),
   724→    DataColumnsByRange(DataColumnsByRangeRequest),
   725→    LightClientBootstrap(LightClientBootstrapRequest),
   726→    LightClientOptimisticUpdate,
   727→    LightClientFinalityUpdate,
   728→    LightClientUpdatesByRange(LightClientUpdatesByRangeRequest),
   729→    Ping(Ping),
   730→    MetaData(MetadataRequest<E>),
   731→}
   732→
   733→/// Implements the encoding per supported protocol for `RPCRequest`.
   734→impl<E: EthSpec> RequestType<E> {
   735→    /* These functions are used in the handler for stream management */
   736→
   737→    /// Maximum number of responses expected for this request.
   738→    pub fn max_responses(&self, digest_epoch: Epoch, spec: &ChainSpec) -> u64 {
   739→        match self {
   740→            RequestType::Status(_) => 1,
   741→            RequestType::Goodbye(_) => 0,
   742→            RequestType::BlocksByRange(req) => *req.count(),
   743→            RequestType::BlocksByRoot(req) => req.block_roots().len() as u64,
   744→            RequestType::BlobsByRange(req) => req.max_blobs_requested(digest_epoch, spec),
   745→            RequestType::BlobsByRoot(req) => req.blob_ids.len() as u64,
   746→            RequestType::DataColumnsByRoot(req) => req.max_requested() as u64,
   747→            RequestType::DataColumnsByRange(req) => req.max_requested::<E>(),
   748→            RequestType::Ping(_) => 1,
   749→            RequestType::MetaData(_) => 1,
   750→            RequestType::LightClientBootstrap(_) => 1,
   751→            RequestType::LightClientOptimisticUpdate => 1,
   752→            RequestType::LightClientFinalityUpdate => 1,
   753→            RequestType::LightClientUpdatesByRange(req) => req.count,
   754→        }
   755→    }
   756→
   757→    /// Gives the corresponding `SupportedProtocol` to this request.
   758→    pub fn versioned_protocol(&self) -> SupportedProtocol {
   759→        match self {
   760→            RequestType::Status(req) => match req {
   761→                StatusMessage::V1(_) => SupportedProtocol::StatusV1,
   762→                StatusMessage::V2(_) => SupportedProtocol::StatusV2,
   763→            },
   764→            RequestType::Goodbye(_) => SupportedProtocol::GoodbyeV1,
   765→            RequestType::BlocksByRange(req) => match req {
   766→                OldBlocksByRangeRequest::V1(_) => SupportedProtocol::BlocksByRangeV1,
   767→                OldBlocksByRangeRequest::V2(_) => SupportedProtocol::BlocksByRangeV2,
   768→            },
   769→            RequestType::BlocksByRoot(req) => match req {
   770→                BlocksByRootRequest::V1(_) => SupportedProtocol::BlocksByRootV1,
   771→                BlocksByRootRequest::V2(_) => SupportedProtocol::BlocksByRootV2,
   772→            },
   773→            RequestType::BlobsByRange(_) => SupportedProtocol::BlobsByRangeV1,
   774→            RequestType::BlobsByRoot(_) => SupportedProtocol::BlobsByRootV1,
   775→            RequestType::DataColumnsByRoot(_) => SupportedProtocol::DataColumnsByRootV1,
   776→            RequestType::DataColumnsByRange(_) => SupportedProtocol::DataColumnsByRangeV1,
   777→            RequestType::Ping(_) => SupportedProtocol::PingV1,
   778→            RequestType::MetaData(req) => match req {
   779→                MetadataRequest::V1(_) => SupportedProtocol::MetaDataV1,
   780→                MetadataRequest::V2(_) => SupportedProtocol::MetaDataV2,
   781→                MetadataRequest::V3(_) => SupportedProtocol::MetaDataV3,
   782→            },
   783→            RequestType::LightClientBootstrap(_) => SupportedProtocol::LightClientBootstrapV1,
   784→            RequestType::LightClientOptimisticUpdate => {
   785→                SupportedProtocol::LightClientOptimisticUpdateV1
   786→            }
   787→            RequestType::LightClientFinalityUpdate => {
   788→                SupportedProtocol::LightClientFinalityUpdateV1
   789→            }
   790→            RequestType::LightClientUpdatesByRange(_) => {
   791→                SupportedProtocol::LightClientUpdatesByRangeV1
   792→            }
   793→        }
   794→    }
   795→
   796→    /// Returns the `ResponseTermination` type associated with the request if a stream gets
   797→    /// terminated.
   798→    pub fn stream_termination(&self) -> ResponseTermination {
   799→        match self {
   800→            // this only gets called after `multiple_responses()` returns true. Therefore, only
   801→            // variants that have `multiple_responses()` can have values.
   802→            RequestType::BlocksByRange(_) => ResponseTermination::BlocksByRange,
   803→            RequestType::BlocksByRoot(_) => ResponseTermination::BlocksByRoot,
   804→            RequestType::BlobsByRange(_) => ResponseTermination::BlobsByRange,
   805→            RequestType::BlobsByRoot(_) => ResponseTermination::BlobsByRoot,
   806→            RequestType::DataColumnsByRoot(_) => ResponseTermination::DataColumnsByRoot,
   807→            RequestType::DataColumnsByRange(_) => ResponseTermination::DataColumnsByRange,
   808→            RequestType::Status(_) => unreachable!(),
   809→            RequestType::Goodbye(_) => unreachable!(),
   810→            RequestType::Ping(_) => unreachable!(),
   811→            RequestType::MetaData(_) => unreachable!(),
   812→            RequestType::LightClientBootstrap(_) => unreachable!(),
   813→            RequestType::LightClientFinalityUpdate => unreachable!(),
   814→            RequestType::LightClientOptimisticUpdate => unreachable!(),
   815→            RequestType::LightClientUpdatesByRange(_) => unreachable!(),
   816→        }
   817→    }
   818→
   819→    pub fn supported_protocols(&self) -> Vec<ProtocolId> {
   820→        match self {
   821→            // add more protocols when versions/encodings are supported
   822→            RequestType::Status(_) => vec![
   823→                ProtocolId::new(SupportedProtocol::StatusV2, Encoding::SSZSnappy),
   824→                ProtocolId::new(SupportedProtocol::StatusV1, Encoding::SSZSnappy),
   825→            ],
   826→            RequestType::Goodbye(_) => vec![ProtocolId::new(
   827→                SupportedProtocol::GoodbyeV1,
   828→                Encoding::SSZSnappy,
   829→            )],
   830→            RequestType::BlocksByRange(_) => vec![
   831→                ProtocolId::new(SupportedProtocol::BlocksByRangeV2, Encoding::SSZSnappy),
   832→                ProtocolId::new(SupportedProtocol::BlocksByRangeV1, Encoding::SSZSnappy),
   833→            ],
   834→            RequestType::BlocksByRoot(_) => vec![
   835→                ProtocolId::new(SupportedProtocol::BlocksByRootV2, Encoding::SSZSnappy),
   836→                ProtocolId::new(SupportedProtocol::BlocksByRootV1, Encoding::SSZSnappy),
   837→            ],
   838→            RequestType::BlobsByRange(_) => vec![ProtocolId::new(
   839→                SupportedProtocol::BlobsByRangeV1,
   840→                Encoding::SSZSnappy,
   841→            )],
   842→            RequestType::BlobsByRoot(_) => vec![ProtocolId::new(
   843→                SupportedProtocol::BlobsByRootV1,
   844→                Encoding::SSZSnappy,
   845→            )],
   846→            RequestType::DataColumnsByRoot(_) => vec![ProtocolId::new(
   847→                SupportedProtocol::DataColumnsByRootV1,
   848→                Encoding::SSZSnappy,
   849→            )],
   850→            RequestType::DataColumnsByRange(_) => vec![ProtocolId::new(
   851→                SupportedProtocol::DataColumnsByRangeV1,
   852→                Encoding::SSZSnappy,
   853→            )],
   854→            RequestType::Ping(_) => vec![ProtocolId::new(
   855→                SupportedProtocol::PingV1,
   856→                Encoding::SSZSnappy,
   857→            )],
   858→            RequestType::MetaData(_) => vec![
   859→                ProtocolId::new(SupportedProtocol::MetaDataV3, Encoding::SSZSnappy),
   860→                ProtocolId::new(SupportedProtocol::MetaDataV2, Encoding::SSZSnappy),
   861→                ProtocolId::new(SupportedProtocol::MetaDataV1, Encoding::SSZSnappy),
   862→            ],
   863→            RequestType::LightClientBootstrap(_) => vec![ProtocolId::new(
   864→                SupportedProtocol::LightClientBootstrapV1,
   865→                Encoding::SSZSnappy,
   866→            )],
   867→            RequestType::LightClientOptimisticUpdate => vec![ProtocolId::new(
   868→                SupportedProtocol::LightClientOptimisticUpdateV1,
   869→                Encoding::SSZSnappy,
   870→            )],
   871→            RequestType::LightClientFinalityUpdate => vec![ProtocolId::new(
   872→                SupportedProtocol::LightClientFinalityUpdateV1,
   873→                Encoding::SSZSnappy,
   874→            )],
   875→            RequestType::LightClientUpdatesByRange(_) => vec![ProtocolId::new(
   876→                SupportedProtocol::LightClientUpdatesByRangeV1,
   877→                Encoding::SSZSnappy,
   878→            )],
   879→        }
   880→    }
   881→
   882→    pub fn expect_exactly_one_response(&self) -> bool {
   883→        match self {
   884→            RequestType::Status(_) => true,
   885→            RequestType::Goodbye(_) => false,
   886→            RequestType::BlocksByRange(_) => false,
   887→            RequestType::BlocksByRoot(_) => false,
   888→            RequestType::BlobsByRange(_) => false,
   889→            RequestType::BlobsByRoot(_) => false,
   890→            RequestType::DataColumnsByRoot(_) => false,
   891→            RequestType::DataColumnsByRange(_) => false,
   892→            RequestType::Ping(_) => true,
   893→            RequestType::MetaData(_) => true,
   894→            RequestType::LightClientBootstrap(_) => true,
   895→            RequestType::LightClientOptimisticUpdate => true,
   896→            RequestType::LightClientFinalityUpdate => true,
   897→            RequestType::LightClientUpdatesByRange(_) => true,
