   973→impl std::error::Error for RPCError {
   974→    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
   975→        match *self {
   976→            // NOTE: this does have a source
   977→            RPCError::SSZDecodeError(_) => None,
   978→            RPCError::IoError(_) => None,
   979→            RPCError::StreamTimeout => None,
   980→            RPCError::UnsupportedProtocol => None,
   981→            RPCError::IncompleteStream => None,
   982→            RPCError::InvalidData(_) => None,
   983→            RPCError::InternalError(_) => None,
   984→            RPCError::ErrorResponse(_, _) => None,
   985→            RPCError::NegotiationTimeout => None,
