   991→    /// Handle a `BlobsByRange` request from the peer.
   992→    fn handle_blobs_by_range_request_inner(
   993→        &self,
   994→        peer_id: PeerId,
   995→        inbound_request_id: InboundRequestId,
   996→        req: BlobsByRangeRequest,
   997→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   998→        debug!(
   999→            ?peer_id,
  1000→            count = req.count,
  1001→            start_slot = req.start_slot,
  1002→            "Received BlobsByRange Request"
  1003→        );
  1004→
  1005→        let request_start_slot = Slot::from(req.start_slot);
  1006→
  1007→        let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
  1008→            Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
  1009→            None => {
  1010→                debug!("Deneb fork is disabled");
  1011→                return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
  1012→            }
  1013→        };
  1014→
  1015→        let oldest_blob_slot = self
  1016→            .chain
  1017→            .store
  1018→            .get_blob_info()
  1019→            .oldest_blob_slot
  1020→            .unwrap_or(data_availability_boundary_slot);
  1021→        if request_start_slot < oldest_blob_slot {
  1022→            debug!(
  1023→                %request_start_slot,
  1024→                %oldest_blob_slot,
  1025→                %data_availability_boundary_slot,
  1026→                "Range request start slot is older than data availability boundary."
  1027→            );
  1028→
  1029→            return if data_availability_boundary_slot < oldest_blob_slot {
  1030→                Err((
  1031→                    RpcErrorResponse::ResourceUnavailable,
  1032→                    "blobs pruned within boundary",
  1033→                ))
  1034→            } else {
  1035→                Err((
  1036→                    RpcErrorResponse::InvalidRequest,
  1037→                    "Req outside availability period",
  1038→                ))
  1039→            };
  1040→        }
  1041→
  1042→        let block_roots =
  1043→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "BlobsByRange")?;
  1044→
  1045→        let current_slot = self
  1046→            .chain
  1047→            .slot()
  1048→            .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());
  1049→
  1050→        let log_results = |peer_id, req: BlobsByRangeRequest, blobs_sent| {
  1051→            debug!(
  1052→                %peer_id,
  1053→                start_slot = req.start_slot,
  1054→                %current_slot,
  1055→                requested = req.count,
  1056→                returned = blobs_sent,
  1057→                "BlobsByRange outgoing response processed"
  1058→            );
  1059→        };
  1060→
  1061→        let mut blobs_sent = 0;
  1062→
  1063→        for root in block_roots {
  1064→            match self.chain.get_blobs(&root) {
  1065→                Ok(blob_sidecar_list) => {
  1066→                    for blob_sidecar in blob_sidecar_list.iter() {
  1067→                        // Due to skip slots, blobs could be out of the range, we ensure they
  1068→                        // are in the range before sending
  1069→                        if blob_sidecar.slot() >= request_start_slot
  1070→                            && blob_sidecar.slot() < request_start_slot + req.count
  1071→                        {
  1072→                            blobs_sent += 1;
  1073→                            self.send_network_message(NetworkMessage::SendResponse {
  1074→                                peer_id,
  1075→                                inbound_request_id,
  1076→                                response: Response::BlobsByRange(Some(blob_sidecar.clone())),
  1077→                            });
  1078→                        }
  1079→                    }
  1080→                }
  1081→                Err(e) => {
  1082→                    error!(
  1083→                        request = ?req,
  1084→                        %peer_id,
  1085→                        block_root = ?root,
  1086→                        error = ?e,
  1087→                        "Error fetching blobs block root"
  1088→                    );
  1089→                    log_results(peer_id, req, blobs_sent);
  1090→
  1091→                    return Err((
  1092→                        RpcErrorResponse::ServerError,
  1093→                        "No blobs and failed fetching corresponding block",
  1094→                    ));
  1095→                }
  1096→            }
  1097→        }
  1098→        log_results(peer_id, req, blobs_sent);
  1099→
  1100→        Ok(())
  1101→    }
