  1133→    /// Handle a `DataColumnsByRange` request from the peer.
  1134→    fn handle_data_columns_by_range_request_inner(
  1135→        &self,
  1136→        peer_id: PeerId,
  1137→        inbound_request_id: InboundRequestId,
  1138→        req: DataColumnsByRangeRequest,
  1139→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
  1140→        debug!(
  1141→            %peer_id,
  1142→            count = req.count,
  1143→            start_slot = req.start_slot,
  1144→            "Received DataColumnsByRange Request"
  1145→        );
  1146→
  1147→        // Should not send more than max request data columns
  1148→        if req.max_requested::<T::EthSpec>() > self.chain.spec.max_request_data_column_sidecars {
  1149→            return Err((
  1150→                RpcErrorResponse::InvalidRequest,
  1151→                "Request exceeded `MAX_REQUEST_BLOBS_SIDECARS`",
  1152→            ));
  1153→        }
  1154→
  1155→        let request_start_slot = Slot::from(req.start_slot);
  1156→
  1157→        let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
  1158→            Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
  1159→            None => {
  1160→                debug!("Deneb fork is disabled");
  1161→                return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
  1162→            }
  1163→        };
  1164→
  1165→        let oldest_data_column_slot = self
  1166→            .chain
  1167→            .store
  1168→            .get_data_column_info()
  1169→            .oldest_data_column_slot
  1170→            .unwrap_or(data_availability_boundary_slot);
  1171→
  1172→        if request_start_slot < oldest_data_column_slot {
  1173→            debug!(
  1174→                %request_start_slot,
  1175→                %oldest_data_column_slot,
  1176→                %data_availability_boundary_slot,
  1177→                "Range request start slot is older than data availability boundary."
  1178→            );
  1179→
  1180→            return if data_availability_boundary_slot < oldest_data_column_slot {
  1181→                Err((
  1182→                    RpcErrorResponse::ResourceUnavailable,
  1183→                    "blobs pruned within boundary",
  1184→                ))
  1185→            } else {
  1186→                Err((
  1187→                    RpcErrorResponse::InvalidRequest,
  1188→                    "Req outside availability period",
  1189→                ))
  1190→            };
  1191→        }
  1192→
  1193→        let block_roots =
  1194→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "DataColumnsByRange")?;
  1195→        let mut data_columns_sent = 0;
  1196→
  1197→        // Only attempt lookups for columns the node has advertised and is responsible for maintaining custody of.
  1198→        let request_start_epoch = request_start_slot.epoch(T::EthSpec::slots_per_epoch());
  1199→        let available_columns = self
  1200→            .chain
  1201→            .custody_columns_for_epoch(Some(request_start_epoch));
  1202→
  1203→        let indices_to_retrieve = req
  1204→            .columns
  1205→            .iter()
  1206→            .copied()
  1207→            .filter(|c| available_columns.contains(c))
  1208→            .collect::<Vec<_>>();
  1209→
  1210→        for root in block_roots {
  1211→            for index in &indices_to_retrieve {
  1212→                match self.chain.get_data_column(&root, index) {
  1213→                    Ok(Some(data_column_sidecar)) => {
  1214→                        // Due to skip slots, data columns could be out of the range, we ensure they
  1215→                        // are in the range before sending
  1216→                        if data_column_sidecar.slot() >= request_start_slot
  1217→                            && data_column_sidecar.slot() < request_start_slot + req.count
  1218→                        {
  1219→                            data_columns_sent += 1;
  1220→                            self.send_network_message(NetworkMessage::SendResponse {
  1221→                                peer_id,
  1222→                                inbound_request_id,
  1223→                                response: Response::DataColumnsByRange(Some(
  1224→                                    data_column_sidecar.clone(),
  1225→                                )),
  1226→                            });
  1227→                        }
  1228→                    }
  1229→                    Ok(None) => {} // no-op
  1230→                    Err(e) => {
